import sys, html, base64, urllib.parse
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_algo=0; self.in_h2=0; self.in_p=0; self.href=''; self.title=''; self.desc=''; self.results=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        cls=a.get('class','')
        if tag=='li' and 'b_algo' in cls: self.in_algo=1; self.title=''; self.desc=''; self.href=''
        elif self.in_algo and tag=='h2': self.in_h2=1
        elif self.in_algo and tag=='p': self.in_p=1
        elif self.in_algo and tag=='a' and self.in_h2: self.href=a.get('href','')
    def handle_data(self, data):
        if self.in_h2: self.title += data
        elif self.in_p: self.desc += data
    def handle_endtag(self, tag):
        if tag=='h2' and self.in_h2: self.in_h2=0
        elif tag=='p' and self.in_p: self.in_p=0
        elif tag=='li' and self.in_algo:
            self.results.append((html.unescape(self.title).strip(), html.unescape(self.href), ' '.join(html.unescape(self.desc).split())))
            self.in_algo=0
for fn in sys.argv[1:]:
    p=P(); p.feed(open(fn,encoding='utf-8').read())
    print('---', fn, '---')
    for t,u,d in p.results[:12]:
        print('TITLE:', t)
        print('HREF:', u)
        if 'u=a1' in u:
            try:
                enc=urllib.parse.parse_qs(urllib.parse.urlsplit(u).query).get('u',[''])[0]
                print('DECODED:', base64.urlsafe_b64decode(enc+'===').decode('utf-8','ignore'))
            except Exception as e: print('DECODE_ERR',e)
        print('DESC:', d[:300])
PY"

